  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * 1. Summary: Computes the final booking price after evaluating membership discount conditions.
   * 2. Algorithm: If customer, customer.membershipPackage, or bookingTime is null or invalid, return this.price. Check if customer.membershipPackage.hasAward(DISCOUNTS) is true. If false, return this.price. Parse bookingTime and combine this.departureDate with this.departureTime to form the departure datetime. If bookingTime is at least 24 hours prior to the departure datetime, apply 20% discount: finalPrice = this.price * 0.8. Else finalPrice = this.price. Format/Round finalPrice to 1 decimal place. Return finalPrice.
   * 3. Related Features: price, departureTime, departureDate
   * 4. Related Classes: Customer, MembershipPackage, Award
   * 5. Input: customer : Customer, bookingTime : String (Full datetime format representing booking creation time)
   * 6. Output: double (value formatted/rounded to 1 decimal place)
   * 7. Pre-condition: Trip object and price field are valid.
   * 8. Post-condition: Returns the calculated price rounded to 1 decimal place. Returns discounted price if eligibility criteria are met, otherwise returns the original this.price.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || customer.getMembershipPackage() == null || bookingTime == null) {
      return this.getPrice();
    }
    if (!customer.getMembershipPackage().hasAward(Award.DISCOUNTS)) {
      return this.getPrice();
    }
    try {
      SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
      sdf.setLenient(false);
      
      Calendar cal = Calendar.getInstance();
      cal.setTime(this.getDepartureDate());
      String[] timeParts = this.getDepartureTime().split(":");
      cal.set(Calendar.HOUR_OF_DAY, Integer.parseInt(timeParts[0]));
      cal.set(Calendar.MINUTE, Integer.parseInt(timeParts[1]));
      cal.set(Calendar.SECOND, timeParts.length > 2 ? Integer.parseInt(timeParts[2]) : 0);
      Date departureDatetime = cal.getTime();

      Date bookingDatetime = sdf.parse(bookingTime);

      long diffMs = departureDatetime.getTime() - bookingDatetime.getTime();
      if (diffMs >= 24 * 60 * 60 * 1000L) {
        double finalPrice = this.getPrice() * 0.8;
        return Math.round(finalPrice * 10.0) / 10.0;
      }
    } catch (Exception e) {
      // Invalid date/time format
    }
    return this.getPrice();
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * 1. Summary: Calculates the monthly reward points generated by this specific trip for a given customer.
   * 2. Algorithm: If customer, customer.membershipPackage, or currentMonth is null or invalid, return 0. If customer.membershipPackage does not contain the POINTS award, return 0. Iterate through this.bookings; for each booking, if it belongs to customer and b.isInMonth(currentMonth) is true, add b.numberOfSeats * 5 to the accumulator. Return the accumulated sum.
   * 3. Related Features: bookings
   * 4. Related Classes: Booking, Customer, Award
   * 5. Input: customer : Customer, currentMonth : String (Format: "YYYY-MM")
   * 6. Output: int
   * 7. Pre-condition: Trip exists and bookings list is initialized.
   * 8. Post-condition: Returns the total points contribution from eligible bookings of the customer for the specified month, or 0 if ineligible or inputs are invalid.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || customer.getMembershipPackage() == null || currentMonth == null) {
      return 0;
    }
    if (!customer.getMembershipPackage().hasAward(Award.POINTS)) {
      return 0;
    }
    int totalPoints = 0;
    for (Booking booking : this.getBookings()) {
      if (booking.getCustomer() == customer && booking.isInMonth(currentMonth)) {
        totalPoints += booking.getNumberOfSeats() * 5;
      }
    }
    return totalPoints;
  }

