      SimpleDateFormat sdf = new SimpleDateFormat("HH:mm:ss");
      sdf.setLenient(false);
      Date d1 = sdf.parse(this.getDepartureTime());
      Date a1 = sdf.parse(this.getArrivalTime());
      Date d2 = sdf.parse(newDepartureTime);
      Date a2 = sdf.parse(newArrivalTime);

